import products from './products.json' with { type: 'json' };

const ALLOWED_ARGS = new Set(['query', 'limit']);

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name (case-insensitive substring match).',
      inputSchema: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'Search term matched against product names, case-insensitively.'
          },
          limit: {
            type: 'integer',
            minimum: 1,
            maximum: 10,
            description: 'Maximum number of results to return (1-10). Defaults to all matches.'
          }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const input = args || {};

  for (const key of Object.keys(input)) {
    if (!ALLOWED_ARGS.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const { query, limit } = input;

  if (typeof query !== 'string') {
    throw new Error('Argument "query" is required and must be a string');
  }

  if (limit !== undefined) {
    if (!Number.isInteger(limit) || limit < 1 || limit > 10) {
      throw new Error('Argument "limit" must be an integer between 1 and 10');
    }
  }

  const needle = query.toLowerCase();
  let matches = products.filter((p) => p.name.toLowerCase().includes(needle));

  if (limit !== undefined) {
    matches = matches.slice(0, limit);
  }

  const text = matches.length === 0
    ? 'No matching products found.'
    : matches.map((p) => `${p.name} [${p.id}]`).join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}

